func productExceptSelf(nums []int) []int {
    n := len(nums)
    res := make([]int, n)

    // 左侧前缀积
    res[0] = 1
    for i := 1; i < n; i++ {
        res[i] = res[i-1] * nums[i-1]
    }

    // 右侧后缀积，直接乘入结果
    right := 1
    for i := n - 2; i >= 0; i-- {
        right *= nums[i+1]
        res[i] *= right
    }
    return res
}
